  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  const act = aS/8, inh = iS/8;
  let hS = 0;
  const hSrc = [[200+Math.sin(t*0.9)*60,100+Math.cos(t*0.7)*40],[280+Math.cos(t*0.8)*50,140+Math.sin(t*1.0)*30],[160+Math.sin(t*1.1+1)*40,160+Math.cos(t*0.6+2)*50]];
  for (const [hX, hY] of hSrc) {
    const d = Math.sqrt((sx-hX)**2 + (sy-hY)**2);
    hS += Math.sin(d*0.2-t*3)*Math.cos(d*0.15+t*2.5);
  }
  hS /= 3;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+Math.sin(sy*0.06+t)*3+t*0.5)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
