  const rings = Math.sin(dist*0.08-t*1.8)*Math.cos(ang*2+t*0.3)*0.3;
  const ljX = cx+Math.sin(t*0.7)*120+Math.sin(t*1.3)*40, ljY = cy+Math.cos(t*0.5)*80+Math.cos(t*1.1)*30;
  const ljD = Math.sqrt((sx-ljX)**2+(sy-ljY)**2);
  const liss = Math.sin(ljD*0.1-t*2.5)*0.25;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*2)*Math.sin(sy*0.25-t*1.5)*0.15;
  const r1 = Math.tanh((act-inh*0.7+bg*0.3+spiral+rings+liss)*2.2);
  const r2 = Math.tanh((inh-act*0.6+hS*0.4+bg*0.2+micro)*2.0);
  const reaction = r1*0.65+r2*0.35;
  const blend = reaction*0.6+cell*0.2+micro*0.2, v = blend*0.5+0.5;
  const pal = [[5,12,55],[10,45,90],[15,85,120],[20,130,130],[60,160,120],[140,180,80],[210,190,60],[230,150,50],[210,100,55],[170,60,60],[120,30,55],[60,15,45],[5,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
